  "hypotheses": [
    {
      "id": "h1",
      "driverType": "booking_error",
      "text": "Duplicate AP invoices were booked for the same vendor invoice number in September, inflating costs.",
      "checks": "SELECT vendor_invoice_no, COUNT(*) AS invoice_cnt FROM lightning.metastore.finmozg.finance_usl.vendor_bill WHERE period='2026-09' GROUP BY vendor_invoice_no HAVING COUNT(*) > 1"
    },
    {
      "id": "h2",
      "driverType": "fx",
      "text": "The USD/CAD rate changed the CAD cost of USD‑denominated vendor invoices between August and September.",
      "checks": "SELECT period, AVG(fx_rate) AS avg_fx_rate FROM lightning.metastore.finmozg.finance_usl.purchase_line WHERE currency='USD' AND period IN ('2026-08','2026-09') GROUP BY period"
    },
    {
      "id": "h3",
      "driverType": "price",
      "text": "Average selling price per unit changed between August and September.",
      "checks": "SELECT period, SUM(revenue_cad)/SUM(qty) AS avg_selling_price_cad FROM lightning.metastore.finmozg.finance_usl.sales_line WHERE period IN ('2026-08','2026-09') GROUP BY period"
    },
    {
      "id": "h4",
      "driverType": "volume",
      "text": "Total units sold changed between August and September.",
      "checks": "SELECT period, SUM(qty) AS total_units_sold FROM lightning.metastore.finmozg.finance_usl.sales_line WHERE period IN ('2026-08','2026-09') GROUP BY period"
    },
    {
      "id": "h5",
      "driverType": "mix",
      "text": "Customer or channel mix shifted between August and September.",
      "checks": "SELECT period, c.channel, SUM(sl.revenue_cad) AS channel_revenue FROM lightning.metastore.finmozg.finance_usl.sales_line sl JOIN lightning.metastore.finmozg.finance_usl.customer c ON sl.customer_id = c.customer_id WHERE sl.period IN ('2026-08','2026-09') GROUP BY period, c.channel"
    },
    {
      "id": "h6",
      "driverType": "supplier_price",
      "text": "Vendor invoiced above contracted unit price for specific SKUs, creating excess COGS.",
      "checks": "SELECT period, SUM((amount_cad) - (qty * contract_unit_price * fx_rate)) AS excess_cad FROM lightning.metastore.finmozg.finance_usl.purchase_line WHERE period IN ('2026-08','2026-09') GROUP BY period"
    },
    {
      "id": "h7",
      "driverType": "opex",
      "text": "Marketing expense (account 6100) changed significantly between August and September.",
      "checks": "SELECT period, amount_cad FROM lightning.metastore.finmozg.finance_usl.gl_balance WHERE account_code='6100' AND period IN ('2026-08','2026-09')"
    }
  ]
}
